/**
 * Date/time formatting functions for display. These functions should be used
 * to get the whole formatted string. DO NOT attempt to create date/time
 * strings by assembling parts.
 */

// NOTE: This module should not be loaded directly, it is available when
// including calUtils.sys.mjs under the cal.dtz.formatter namespace.

formatInterval(startDate, endDate) {
  if (endDate == null && startDate == null) {
    return lazy.l10n.formatValueSync("datetime-interval-task-without-date");
  }

  if (endDate == null) {
    return lazy.l10n.formatValueSync("datetime-interval-task-without-due-date", {
      date: this.formatDate(startDate),
      time: this.formatTime(startDate),
    });
  }

  if (startDate == null) {
    return lazy.l10n.formatValueSync("datetime-interval-task-without-start-date", {
      date: this.formatDate(endDate),
      time: this.formatTime(endDate),
    });

  //9: same-day
  {
    input: {
      start: "20220916T140000Z",
      end: "20220916T160000Z",
    },
    expected: [
      "Friday, September 16, 2022, 2:00 – 4:00 PM",
      "Friday, September 16, 2022, 14:00 – 16:00",
    ],
  },
  //10: several-days
  {
    input: {
      start: "20220916T140000Z",
      end: "20220920T160000Z",
    },
    expected: [
      "Friday, September 16, 2022 at 2:00 PM – Tuesday, September 20, 2022 at 4:00 PM",
      "Friday, September 16, 2022 at 14:00 – Tuesday, September 20, 2022 at 16:00",
    ],
  },
];

let i = 0;
for (const test of data) {
  i++;
  const startDate = test.input.start ? cal.createDateTime(test.input.start) : null;
  const endDate = test.input.end ? cal.createDateTime(test.input.end) : null;

  const formatted = formatter.formatInterval(startDate, endDate);
  ok(
    test.expected.includes(formatted),
    "(test #" + i + ": result '" + formatted + "', expected '" + test.expected + "')"
